import decimal
import re

def summarize(batches, rule):
    if rule != 'invoice-v1':
        raise ValueError('rule')
    units = {'USD': decimal.Decimal('.01'), 'EUR': decimal.Decimal('.01'),
             'JPY': decimal.Decimal(1)}
    sums = {}
    count = 0
    for batch in batches:
        for row in batch:
            count += 1
            if count > 10000 or not isinstance(row, dict) or set(row) != {'currency', 'amount'}:
                raise ValueError('rows')
            currency, amount = row['currency'], row['amount']
            if (currency not in units or not isinstance(amount, str)
                    or not re.fullmatch(r'-?(?:0|[1-9][0-9]{0,29})(?:\.[0-9]{1,6})?', amount)):
                raise ValueError('amount')
            whole, point, fraction = amount.lstrip('-').partition('.')
            micro = int(whole)*1000000 + int(fraction.ljust(6, '0') or '0')
            if amount.startswith('-'):
                micro = -micro
            sums[currency] = sums.get(currency, 0) + micro
    with decimal.localcontext(decimal.Context(prec=60, rounding=decimal.ROUND_HALF_EVEN)):
        totals = {code: decimal.Decimal(value).scaleb(-6).quantize(
                      units[code], rounding=decimal.ROUND_HALF_EVEN)
                  for code, value in sorted(sums.items())}
    return {'rule': rule, 'totals': totals}
